/* Reuse existing, original WortWeg multilingual grammar lesson references. */
window.WWGLifeLessons=[{"level":"A1","title":"Definite articles","rule":"der / die / das mark grammatical gender and the nominative case.","pattern":"der Mann · die Frau · das Kind","de":"Der Mann kommt.","en":"The man is coming.","my":"အမျိုးသား လာနေသည်။","question":"___ Frau lernt Deutsch.","options":["Die","Der","Das","Den"]},{"level":"A1","title":"Indefinite articles","rule":"ein is masculine/neuter and eine is feminine in nominative.","pattern":"ein Tisch · eine Lampe · ein Buch","de":"Das ist eine Lampe.","en":"That is a lamp.","my":"အဲဒါ မီးအိမ်တစ်လုံးပါ။","question":"Das ist ___ Buch.","options":["ein","eine","einen","einem"]},{"level":"A1","title":"Personal pronouns","rule":"Subject pronouns replace nouns: ich, du, er, sie, es, wir, ihr, sie, Sie.","pattern":"ich · du · wir · Sie","de":"Wir lernen Deutsch.","en":"We are learning German.","my":"ကျွန်ုပ်တို့ ဂျာမန်စာ သင်နေကြသည်။","question":"___ lerne Deutsch.","options":["Ich","Du","Wir","Ihr"]},{"level":"A1","title":"Present tense regular verbs","rule":"Many regular verbs take -e, -st, -t, -en, -t, -en endings.","pattern":"ich lerne · du lernst · er lernt","de":"Du lernst schnell.","en":"You learn quickly.","my":"မင်း သင်ယူတာ မြန်တယ်။","question":"Er ___ Deutsch.","options":["lernt","lernen","lerne","lernst"]},{"level":"A1","title":"Sein and haben","rule":"sein (to be) and haben (to have) are irregular present-tense verbs.","pattern":"ich bin · du bist · er ist","de":"Ich habe Zeit.","en":"I have time.","my":"ကျွန်တော့်မှာ အချိန်ရှိတယ်။","question":"Wir ___ müde.","options":["sind","ist","seid","bin"]},{"level":"A1","title":"Verb second position","rule":"In a declarative main clause the finite verb occupies the second syntactic position.","pattern":"Heute | lerne | ich Deutsch.","de":"Heute lerne ich Deutsch.","en":"Today I am learning German.","my":"ဒီနေ့ ကျွန်တော် ဂျာမန်စာ သင်နေတယ်။","question":"Heute ___ ich Deutsch.","options":["lerne","ich lerne","lernen","gelernt"]},{"level":"A1","title":"Negation kein","rule":"Use kein to negate many indefinite noun phrases; its ending changes with case/gender.","pattern":"kein Buch · keine Zeit","de":"Ich habe keine Zeit.","en":"I have no time.","my":"ကျွန်တော့်မှာ အချိန်မရှိဘူး။","question":"Ich habe ___ Auto.","options":["kein","keine","nicht","keinen"]},{"level":"A1","title":"Accusative articles","rule":"Masculine definite article der becomes den as an accusative direct object.","pattern":"der Mann → den Mann","de":"Ich sehe den Mann.","en":"I see the man.","my":"အဲဒီ အမျိုးသားကို ကျွန်တော် မြင်တယ်။","question":"Ich sehe ___ Hund.","options":["den","der","dem","das"]},{"level":"A2","title":"Perfect tense haben or sein","rule":"The Perfekt uses haben or sein with a past participle; motion/change-of-state verbs often use sein.","pattern":"hat gelernt · ist gegangen","de":"Ich bin nach Hause gegangen.","en":"I went home.","my":"ကျွန်တော် အိမ်ပြန်ခဲ့တယ်။","question":"Ich ___ nach Berlin gefahren.","options":["bin","habe","werde","war"]},{"level":"A2","title":"Dative articles","rule":"Dative definite articles are dem (m/n), der (f), den (plural).","pattern":"mit dem Mann · mit der Frau","de":"Ich helfe dem Kind.","en":"I help the child.","my":"ကလေးကို ကျွန်တော် ကူညီတယ်။","question":"Ich helfe ___ Frau.","options":["der","die","den","das"]},{"level":"A2","title":"Two-way prepositions","rule":"With in, an, auf, unter etc., use accusative for direction and dative for location.","pattern":"in die Schule / in der Schule","de":"Das Buch liegt auf dem Tisch.","en":"The book is on the table.","my":"စာအုပ်က စားပွဲပေါ်မှာ ရှိတယ်။","question":"Ich lege das Buch auf ___ Tisch.","options":["den","dem","der","das"]},{"level":"A2","title":"Subordinate clauses weil","rule":"weil introduces a reason and sends the finite verb to the end of its clause.","pattern":"weil ich müde bin","de":"Ich bleibe zu Hause, weil ich krank bin.","en":"I stay home because I am ill.","my":"နေမကောင်းလို့ အိမ်မှာပဲ နေတယ်။","question":"Ich bleibe da, weil ich müde ___.","options":["bin","ich","bist","sein"]},{"level":"A2","title":"Adjective endings after definite articles","rule":"After a definite article, adjectives usually take -e or -en depending on case and form.","pattern":"der kleine Hund · den kleinen Hund","de":"Ich sehe den kleinen Hund.","en":"I see the small dog.","my":"ခွေးသေးလေးကို မြင်တယ်။","question":"Das ist der ___ Mann.","options":["alte","alten","alter","altes"]},{"level":"A2","title":"Comparative adjectives","rule":"The comparative often adds -er; als introduces the comparison.","pattern":"schnell → schneller als","de":"Berlin ist größer als Bonn.","en":"Berlin is bigger than Bonn.","my":"ဘာလင်မြို့က ဘွန်မြို့ထက် ပိုကြီးတယ်။","question":"Sie ist ___ als ich.","options":["älter","alt","am ältesten","alte"]},{"level":"A2","title":"Indirect questions","rule":"Indirect yes/no questions use ob and send the finite verb to clause-final position.","pattern":"ob er kommt","de":"Ich weiß nicht, ob er kommt.","en":"I do not know whether he is coming.","my":"သူလာမလား မသိဘူး။","question":"Ich frage, ___ er kommt.","options":["ob","wenn","denn","aber"]},{"level":"B1","title":"Relative clauses nominative","rule":"A relative clause modifies a noun; the pronoun agrees in gender/number and takes case from its role.","pattern":"der Mann, der dort wohnt","de":"Das ist die Frau, die hier arbeitet.","en":"That is the woman who works here.","my":"ဒါက ဒီမှာ အလုပ်လုပ်တဲ့ အမျိုးသမီးပါ။","question":"Das ist der Mann, ___ hier wohnt.","options":["der","den","dem","das"]},{"level":"B1","title":"Passive present","rule":"The process passive is formed with werden plus Partizip II.","pattern":"wird gemacht · werden gebaut","de":"Das Haus wird gebaut.","en":"The house is being built.","my":"အိမ်ကို ဆောက်လုပ်နေသည်။","question":"Der Brief ___ geschrieben.","options":["wird","ist","hat","war"]},{"level":"B1","title":"Konjunktiv II wäre/hätte","rule":"Konjunktiv II expresses imaginary situations, wishes and polite requests.","pattern":"wäre · hätte · könnte","de":"Wenn ich Zeit hätte, käme ich.","en":"If I had time, I would come.","my":"အချိန်ရှိခဲ့ရင် လာမိမှာပါ။","question":"Wenn ich reich ___, würde ich reisen.","options":["wäre","bin","ist","sei"]},{"level":"B1","title":"Purpose clauses um zu","rule":"Use um ... zu + infinitive when the subject is the same in both clauses.","pattern":"um Deutsch zu lernen","de":"Ich lerne, um die Prüfung zu bestehen.","en":"I study to pass the exam.","my":"စာမေးပွဲ အောင်ဖို့ စာကျက်တယ်။","question":"Ich lerne, ___ die Prüfung zu bestehen.","options":["um","weil","dass","ob"]},{"level":"B1","title":"Plusquamperfekt","rule":"Past perfect combines hatte/war with Partizip II for an earlier past event.","pattern":"hatte gelernt · war gefahren","de":"Sie hatte schon gegessen.","en":"She had already eaten.","my":"သူမ အရင်ကတည်းက စားပြီးသား ဖြစ်ခဲ့တယ်။","question":"Er ___ schon gegangen.","options":["war","hat","wird","ist"]},{"level":"B1","title":"Temporal clauses nachdem","rule":"nachdem describes an event completed before another; tense choice expresses chronology.","pattern":"Nachdem ich gegessen hatte, ...","de":"Nachdem er gegessen hatte, ging er los.","en":"After he had eaten, he left.","my":"စားပြီးနောက် သူ ထွက်သွားတယ်။","question":"___ sie angekommen war, rief sie an.","options":["Nachdem","Während","Damit","Ob"]},{"level":"B2","title":"State passive vs process passive","rule":"werden + participle describes the process; sein + participle describes the resulting state.","pattern":"Die Tür wird geöffnet / ist geöffnet.","de":"Die Tür ist geschlossen.","en":"The door is closed.","my":"တံခါး ပိတ်ထားတယ်။","question":"Die Tür ___ geöffnet worden.","options":["ist","hat","wäre","wird"]},{"level":"B2","title":"Proportional je desto","rule":"je + comparative in the first clause correlates with desto/umso + comparative in the next.","pattern":"Je mehr ..., desto besser ...","de":"Je mehr ich übe, desto sicherer werde ich.","en":"The more I practise, the more confident I become.","my":"လေ့ကျင့်လေလေ ယုံကြည်မှု ပိုရှိလေလေ။","question":"Je länger wir warten, ___ später wird es.","options":["desto","als","weil","obwohl"]},{"level":"B2","title":"Nominalisation verbs","rule":"Turn verb phrases into noun phrases for denser formal style.","pattern":"weil es regnet → wegen des Regens","de":"Wegen des Regens bleiben wir hier.","en":"Because of the rain, we are staying here.","my":"မိုးကြောင့် ဒီမှာ နေမယ်။","question":"___ des Wetters bleiben wir zu Hause.","options":["Wegen","Weil","Damit","Obwohl"]},{"level":"B2","title":"Extended participial attributes","rule":"Participles can carry modifiers before a noun in formal written German.","pattern":"der gestern veröffentlichte Bericht","de":"Der gestern veröffentlichte Bericht ist wichtig.","en":"The report published yesterday is important.","my":"မနေ့က ထုတ်ဝေခဲ့တဲ့ အစီရင်ခံစာက အရေးကြီးတယ်။","question":"Der gestern ___ Bericht ist wichtig.","options":["veröffentlichte","veröffentlicht","veröffentlichen","veröffentliche"]},{"level":"B2","title":"Passive alternatives sein zu","rule":"sein + zu + infinitive expresses necessity or possibility, depending on context.","pattern":"Der Text ist zu lesen.","de":"Die Aufgabe ist leicht zu lösen.","en":"The task is easy to solve.","my":"ဒီတာဝန်က ဖြေရှင်းဖို့ လွယ်တယ်။","question":"Die Frage ist noch ___ klären.","options":["zu","um","mit","an"]},{"level":"B2","title":"Reported statements","rule":"Use indirect speech and reported-speech forms when quoting another person's statement indirectly.","pattern":"Er sagt, er sei krank.","de":"Sie sagt, sie habe keine Zeit.","en":"She says she has no time.","my":"သူမက အချိန်မရှိဘူးလို့ ပြောတယ်။","question":"Er behauptet, er ___ unschuldig.","options":["sei","ist","sein","sind"]},{"level":"C1","title":"Konjunktiv I reported speech","rule":"Konjunktiv I signals indirect reported statements and speaker distance.","pattern":"er sei · er habe · sie gehe","de":"Die Zeugin erklärte, sie habe nichts gesehen.","en":"The witness stated that she had seen nothing.","my":"သက်သေက ဘာမှ မမြင်ခဲ့ဘူးလို့ ရှင်းပြခဲ့တယ်။","question":"Der Sprecher erklärte, er ___ informiert.","options":["sei","ist","war","sind"]},{"level":"C1","title":"Complex nominalization","rule":"Academic writing often compresses a clause into a nominal phrase; ensure relationships stay clear.","pattern":"Nachdem man geprüft hatte → nach der Prüfung","de":"Nach der Auswertung wurden die Ergebnisse veröffentlicht.","en":"After the evaluation, the results were published.","my":"အကဲဖြတ်ပြီးနောက် ရလဒ်တွေကို ထုတ်ပြန်ခဲ့တယ်။","question":"___ Abschluss der Untersuchung folgte ein Bericht.","options":["Nach","Damit","Obwohl","Während"]},{"level":"C1","title":"Modal verb epistemic meaning","rule":"Modal verbs can express the speaker's assessment rather than permission or obligation.","pattern":"Er dürfte zu Hause sein.","de":"Er muss davon gewusst haben.","en":"He must have known about it.","my":"ဒီအကြောင်းကို သူ သိထားခဲ့တာ သေချာသလောက်ပဲ။","question":"Sie ___ bereits abgereist sein. (strong inference)","options":["muss","darf","will","mag"]},{"level":"C1","title":"Subjunctive distancing","rule":"Reported-speech subjunctive and cautious wording convey source attribution rather than certainty.","pattern":"angeblich · er habe · soll","de":"Der Bericht zufolge sei die Lage stabil.","en":"According to the report, the situation is stable.","my":"အစီရင်ခံစာအရ အခြေအနေ တည်ငြိမ်နေတယ်လို့ ဆိုတယ်။","question":"Laut Pressemitteilung ___ das Projekt abgeschlossen.","options":["sei","ist","sind","waren"]},{"level":"C1","title":"Information structure emphasis","rule":"Fronting adverbials or objects changes emphasis while preserving the finite-verb position.","pattern":"Besonders wichtig ist ...","de":"Besonders wichtig ist die Datensicherheit.","en":"Data security is especially important.","my":"အထူးအရေးကြီးတာက ဒေတာလုံခြုံရေးပါ။","question":"Besonders wichtig ___ die Kontrolle.","options":["ist","sind","sein","hat"]},{"level":"C1","title":"Academic connective structures","rule":"Formal connectors link claims precisely (concessive, causal, contrastive, consecutive).","pattern":"hingegen · folglich · demgegenüber","de":"Die Kosten steigen; folglich sinkt der Gewinn.","en":"Costs rise; consequently, profit falls.","my":"ကုန်ကျစရိတ် မြင့်လာတာကြောင့် အမြတ်လျော့သွားတယ်။","question":"Die Nachfrage sank; ___ wurde die Produktion reduziert.","options":["folglich","trotz","denn","während"]},{"level":"A1","title":"Alphabet & spelling","rule":"German uses 26 base letters plus ä, ö, ü and ß. Capitalize all nouns; ß generally represents /s/ after long vowels or diphthongs.","pattern":"ä · ö · ü · ß","de":"Die Straße ist lang.","en":"The street is long.","my":"လမ်းက ရှည်တယ်။","question":"Which noun must be capitalized?","options":["Straße","straße","straSSe","strasse"]},{"level":"A1","title":"Nouns and gender","rule":"Every German noun has a grammatical gender (masculine, feminine or neuter). Learn the definite article with each noun.","pattern":"der Tisch · die Lampe · das Haus","de":"Das Haus ist neu.","en":"The house is new.","my":"အိမ်က အသစ်ပါ။","question":"Which article belongs to Haus?","options":["das","die","der","den"]},{"level":"A1","title":"Present tense irregular verbs","rule":"Some common verbs change their stem vowel in du/er/sie/es: fahren → du fährst, er fährt; lesen → du liest.","pattern":"fahren → du fährst","de":"Er fährt nach Hamburg.","en":"He travels to Hamburg.","my":"သူ ဟမ်းဘတ်ကို သွားတယ်။","question":"Du ___ nach Hause.","options":["fährst","fahrt","fahren","fahre"]},{"level":"A1","title":"Yes/no questions","rule":"In direct yes/no questions, the finite verb comes first, followed by the subject.","pattern":"Kommst du? · Hast du Zeit?","de":"Sprichst du Deutsch?","en":"Do you speak German?","my":"မင်း ဂျာမန်စကား ပြောတတ်လား။","question":"___ du Deutsch?","options":["Sprichst","Du sprichst","Sprechen","Sprich"]},{"level":"A1","title":"W-questions","rule":"Place a question word such as wer, was, wo, wann, warum or wie first; the finite verb follows.","pattern":"Wo wohnst du?","de":"Wann beginnt der Kurs?","en":"When does the course begin?","my":"သင်တန်း ဘယ်အချိန် စမလဲ။","question":"___ wohnst du? (where)","options":["Wo","Was","Wann","Warum"]},{"level":"A1","title":"Negation nicht","rule":"Use nicht to negate a verb, adjective, adverb or definite phrase; its position depends on scope.","pattern":"nicht teuer · ich komme nicht","de":"Das ist nicht teuer.","en":"That is not expensive.","my":"ဒါက ဈေးမကြီးဘူး။","question":"Das Auto ist ___ neu.","options":["nicht","kein","keine","keinen"]},{"level":"A1","title":"Nominative","rule":"The nominative marks the subject of a finite clause and predicate nouns after sein/werden/bleiben.","pattern":"der Mann · die Frau","de":"Der Hund schläft.","en":"The dog is sleeping.","my":"ခွေးက အိပ်နေတယ်။","question":"___ Hund schläft.","options":["Der","Den","Dem","Des"]},{"level":"A1","title":"Possessive determiners","rule":"Possessives mein, dein, sein, ihr, unser and euer take adjective-like endings based on case, gender and number.","pattern":"mein Bruder · meine Schwester","de":"Meine Mutter arbeitet.","en":"My mother works.","my":"အမေ အလုပ်လုပ်တယ်။","question":"Das ist ___ Schwester.","options":["meine","mein","meinen","meinem"]},{"level":"A1","title":"Plural nouns","rule":"German has several plural patterns: -e, -er, -n/-en, -s, zero and sometimes an umlaut. Memorize the plural with each noun.","pattern":"das Kind → die Kinder","de":"Die Kinder spielen.","en":"The children are playing.","my":"ကလေးတွေ ကစားနေကြတယ်။","question":"das Kind → die ___","options":["Kinder","Kinde","Kinds","Kindern"]},{"level":"A1","title":"Modal verbs können","rule":"können expresses ability or possibility; conjugate the modal in second position, with the lexical infinitive at the end.","pattern":"ich kann · du kannst","de":"Ich kann schwimmen.","en":"I can swim.","my":"ကျွန်တော် ရေကူးတတ်တယ်။","question":"Er ___ gut singen.","options":["kann","können","kannst","könnt"]},{"level":"A1","title":"Separable verbs","rule":"In a main clause, the stressed separable prefix moves to the end: aufstehen → ich stehe auf.","pattern":"aufstehen → steht ... auf","de":"Sie steht früh auf.","en":"She gets up early.","my":"သူမ စောစောထတယ်။","question":"Ich stehe um sieben Uhr ___.","options":["auf","an","aus","ein"]},{"level":"A1","title":"Imperative","rule":"For informal du commands, often use the stem (Komm!); ihr commands use the ihr-form without pronoun (Kommt!). Formal requests use Sie.","pattern":"Komm! · Kommt! · Kommen Sie!","de":"Bitte kommen Sie herein!","en":"Please come in!","my":"ကျေးဇူးပြုပြီး အထဲကို ဝင်ပါ။","question":"___ bitte! (du: come)","options":["Komm","Kommt","Kommen","Kommst"]},{"level":"A1","title":"Coordinating conjunctions","rule":"und, aber, oder, denn and sondern connect coordinate clauses without moving the finite verb to clause-final position.","pattern":"Ich lerne, aber ich bin müde.","de":"Ich lerne Deutsch, aber es ist schwer.","en":"I study German, but it is difficult.","my":"ဂျာမန်စာ သင်တယ်၊ ဒါပေမယ့် ခက်တယ်။","question":"Ich komme, ___ ich habe Zeit.","options":["denn","weil","dass","ob"]},{"level":"A1","title":"Es gibt","rule":"es gibt means there is/there are and takes an accusative object.","pattern":"Es gibt einen Park.","de":"Hier gibt es einen Bahnhof.","en":"There is a train station here.","my":"ဒီမှာ ဘူတာရုံတစ်ခုရှိတယ်။","question":"Hier gibt es ___ Park.","options":["einen","ein","einem","einer"]},{"level":"A1","title":"Adjectives predicative","rule":"Adjectives after sein, werden and bleiben are predicative and carry no declension ending.","pattern":"Das Haus ist groß.","de":"Der Kaffee ist heiß.","en":"The coffee is hot.","my":"ကော်ဖီက ပူတယ်။","question":"Die Bücher sind ___.","options":["neu","neuen","neue","neues"]},{"level":"A1","title":"Formal Sie","rule":"Formal Sie is capitalized and combines with third-person plural verb forms.","pattern":"Kommen Sie! · Haben Sie?","de":"Woher kommen Sie?","en":"Where are you from?","my":"ဘယ်က လာတာပါလဲ။","question":"___ Sie Deutsch?","options":["Sprechen","Sprichst","Spricht","Sprecht"]},{"level":"A2","title":"Past participles regular","rule":"Regular weak verbs typically form Partizip II with ge- + stem + -t; many inseparable prefixes omit ge-.","pattern":"machen → gemacht","de":"Wir haben gestern gekocht.","en":"We cooked yesterday.","my":"မနေ့က ကျွန်တော်တို့ ချက်ပြုတ်ခဲ့တယ်။","question":"machen → ___","options":["gemacht","gemachen","gemachte","gemachtet"]},{"level":"A2","title":"Präteritum sein/haben","rule":"The simple past of sein and haben commonly describes past states and possession in speech and writing.","pattern":"ich war · du warst · wir hatten","de":"Gestern war ich krank.","en":"I was ill yesterday.","my":"မနေ့က ကျွန်တော် နေမကောင်းခဲ့ဘူး။","question":"Früher ___ ich ein Fahrrad.","options":["hatte","habe","haben","hättest"]},{"level":"A2","title":"Reflexive verbs","rule":"Reflexive verbs require a pronoun referring back to the subject. The pronoun may be accusative or dative.","pattern":"sich freuen → ich freue mich","de":"Ich freue mich auf den Urlaub.","en":"I look forward to the holiday.","my":"အားလပ်ရက်အတွက် ဝမ်းသာမျှော်လင့်နေတယ်။","question":"Ich interessiere ___ für Musik.","options":["mich","mir","dich","sich"]},{"level":"A2","title":"Subordinate clauses dass","rule":"dass introduces a content clause and sends the finite verb to the end.","pattern":"Ich glaube, dass er kommt.","de":"Ich hoffe, dass du Zeit hast.","en":"I hope you have time.","my":"မင်းမှာ အချိန်ရှိမယ်လို့ မျှော်လင့်တယ်။","question":"Ich denke, ___ es klappt.","options":["dass","das","denn","aber"]},{"level":"A2","title":"Future werden","rule":"Futur I combines finite werden plus an infinitive, though present tense also expresses future when context is clear.","pattern":"ich werde lernen","de":"Morgen werde ich lernen.","en":"Tomorrow I will study.","my":"မနက်ဖြန် စာကျက်မယ်။","question":"Wir ___ morgen arbeiten.","options":["werden","wird","werdet","werde"]},{"level":"A2","title":"Conjunction obwohl","rule":"obwohl introduces a concession and sends the verb to the end of the subordinate clause.","pattern":"obwohl es regnet","de":"Obwohl es regnet, gehe ich spazieren.","en":"Although it is raining, I am going for a walk.","my":"မိုးရွာပေမယ့် လမ်းလျှောက်ထွက်မယ်။","question":"___ er müde ist, arbeitet er.","options":["Obwohl","Denn","Aber","Oder"]},{"level":"A2","title":"Connectors deshalb trotzdem","rule":"deshalb signals consequence; trotzdem marks contrast. They are adverbs and occupy a sentence position, so the finite verb follows.","pattern":"Es regnet. Trotzdem gehe ich.","de":"Es regnet; deshalb bleibe ich zu Hause.","en":"It's raining; therefore I stay home.","my":"မိုးရွာလို့ အိမ်မှာ နေမယ်။","question":"Ich bin krank; ___ bleibe ich daheim.","options":["deshalb","obwohl","dass","weil"]},{"level":"A2","title":"Position of nicht","rule":"nicht normally follows many objects but precedes a negated adjective, adverb, separable prefix or final infinitive depending on scope.","pattern":"Ich kenne ihn nicht.","de":"Ich verstehe das nicht.","en":"I don't understand that.","my":"အဲဒါကို နားမလည်ဘူး။","question":"Ich bin ___ müde.","options":["nicht","kein","keine","keinen"]},{"level":"B1","title":"Relative clauses accusative","rule":"Use accusative relative pronouns when the noun referred to functions as a direct object within the relative clause.","pattern":"der Mann, den ich sehe","de":"Das ist der Film, den ich mag.","en":"That's the film I like.","my":"ဒါက ကျွန်တော် ကြိုက်တဲ့ ရုပ်ရှင်ပါ။","question":"Der Mann, ___ ich kenne, kommt.","options":["den","der","dem","dessen"]},{"level":"B1","title":"Relative clauses dative","rule":"Use dative relative pronouns when required by the verb or preposition within the relative clause.","pattern":"die Frau, der ich helfe","de":"Das ist der Mann, dem ich helfe.","en":"That is the man I help.","my":"ဒါက ကျွန်တော် ကူညီနေတဲ့ အမျိုးသားပါ။","question":"Der Mann, ___ ich danke, ist hier.","options":["dem","den","der","das"]},{"level":"B1","title":"Passive past","rule":"The Präteritum process passive uses wurde(n) + Partizip II.","pattern":"wurde gebaut · wurden geöffnet","de":"Die Brücke wurde gebaut.","en":"The bridge was built.","my":"တံတားကို ဆောက်လုပ်ခဲ့တယ်။","question":"Das Fenster ___ geöffnet.","options":["wurde","war","hatte","ist"]},{"level":"B1","title":"Konjunktiv II würde","rule":"würde + infinitive forms many hypothetical statements and polite expressions.","pattern":"ich würde gehen","de":"Ich würde gern länger bleiben.","en":"I would like to stay longer.","my":"နည်းနည်းပိုကြာကြာ နေချင်ပါတယ်။","question":"Ich ___ gern reisen.","options":["würde","werde","wurde","wird"]},{"level":"B1","title":"Purpose clauses damit","rule":"Use damit + subordinate clause to express purpose, especially when subjects differ.","pattern":"damit du es verstehst","de":"Ich erkläre es, damit du es verstehst.","en":"I explain it so you understand it.","my":"မင်း နားလည်အောင် ရှင်းပြတာပါ။","question":"Ich spreche langsam, ___ du mich verstehst.","options":["damit","weil","ob","denn"]},{"level":"B1","title":"Temporal clauses bevor","rule":"bevor means before; it introduces a subordinate clause with final finite verb.","pattern":"bevor er geht","de":"Bevor ich gehe, rufe ich dich an.","en":"Before I leave, I'll call you.","my":"ကျွန်တော် မသွားခင် မင်းကို ဖုန်းခေါ်မယ်။","question":"___ du gehst, schließ die Tür.","options":["Bevor","Nachdem","Damit","Seitdem"]},{"level":"B1","title":"Double connectors entweder oder","rule":"entweder ... oder presents two alternatives and can connect words, phrases or clauses.","pattern":"entweder heute oder morgen","de":"Entweder wir fahren oder wir bleiben.","en":"Either we leave or we stay.","my":"သွားမယ်၊ မသွားဘဲ နေမယ် ဆိုတာ နှစ်ခုထဲက တစ်ခုပါ။","question":"___ du kommst oder du rufst an.","options":["Entweder","Sowohl","Weder","Zwar"]},{"level":"B1","title":"N-declension","rule":"Certain masculine nouns take -(e)n in most forms outside nominative singular, e.g. der Student → den Studenten.","pattern":"der Student / den Studenten","de":"Ich kenne den Studenten.","en":"I know the student.","my":"ဒီကျောင်းသားကို သိတယ်။","question":"Ich spreche mit dem ___.","options":["Studenten","Student","Students","Studentes"]},{"level":"B2","title":"Modal particles","rule":"Modal particles like doch, ja and mal add pragmatic nuance and cannot always be translated word for word.","pattern":"Komm doch mal!","de":"Komm doch mal vorbei!","en":"Do come by sometime!","my":"တစ်ခါလောက် ဝင်လည်ပါဦး။","question":"Komm ___ vorbei! (friendly encouragement)","options":["doch","weil","dass","aber"]},{"level":"B2","title":"Subjective modal verbs","rule":"Modal verbs such as müssen, dürfen and können can express certainty or likelihood rather than obligation or ability.","pattern":"Das dürfte stimmen.","de":"Das dürfte richtig sein.","en":"That is probably correct.","my":"အဲဒါ မှန်နိုင်ခြေများတယ်။","question":"Er ___ schon zu Hause sein. (likely)","options":["dürfte","müsste nicht","wollte","soll"]},{"level":"B2","title":"Nominal style formal writing","rule":"Nominal style replaces subordinate clauses with noun phrases, common in official and academic texts, but can reduce readability.","pattern":"wegen des Sturms statt weil es stürmt","de":"Aufgrund des Wetters fällt die Fahrt aus.","en":"The trip is cancelled because of the weather.","my":"ရာသီဥတုကြောင့် ခရီးစဉ် ဖျက်သိမ်းတယ်။","question":"___ des Sturms fiel der Zug aus.","options":["Wegen","Weil","Obwohl","Damit"]},{"level":"B2","title":"Relative clauses with was","rule":"After indefinite pronouns like alles, etwas, nichts and whole-clause antecedents, use was rather than das as relative pronoun.","pattern":"alles, was ich weiß","de":"Alles, was er sagt, ist wichtig.","en":"Everything he says is important.","my":"သူပြောတဲ့ အရာအားလုံး အရေးကြီးတယ်။","question":"Das ist alles, ___ ich weiß.","options":["was","das","der","dem"]},{"level":"B2","title":"Funktionsverbgefüge","rule":"Functional verb constructions combine a semantically light verb and noun, e.g. eine Entscheidung treffen rather than entscheiden.","pattern":"eine Entscheidung treffen","de":"Wir treffen eine Entscheidung.","en":"We make a decision.","my":"ကျွန်တော်တို့ ဆုံးဖြတ်ချက်ချမယ်။","question":"Wir ___ eine Entscheidung.","options":["treffen","machen zu","gehen","bringen aus"]},{"level":"B2","title":"Concessive obwohl wenngleich","rule":"Although obwohl and wenngleich both signal concession, wenngleich sounds more formal.","pattern":"wenngleich die Daten fehlen","de":"Wenngleich die Aufgabe schwierig ist, lösen wir sie.","en":"Although the task is difficult, we solve it.","my":"တာဝန်က ခက်ပေမယ့် ဖြေရှင်းမယ်။","question":"___ es teuer ist, kaufen wir es.","options":["Wenngleich","Deshalb","Denn","Oder"]},{"level":"C1","title":"Konjunktiv I replacement forms","rule":"When Konjunktiv I equals indicative, reported speech often uses Konjunktiv II to keep the distinction.","pattern":"sie sagen → sie sagten (replacement)","de":"Sie erklärten, sie hätten keine Zeit.","en":"They explained they had no time.","my":"သူတို့မှာ အချိန်မရှိဘူးလို့ ရှင်းပြခဲ့တယ်။","question":"Die Zeugen erklärten, sie ___ nichts gesehen.","options":["hätten","haben","hat","hatten werden"]},{"level":"C1","title":"Indirect commands and questions","rule":"Reported instructions often use sollen + infinitive; reported questions use ob or a question word with clause-final verb.","pattern":"Er fragte, ob ...","de":"Sie fragte, wann der Zug abfahre.","en":"She asked when the train would depart.","my":"ရထား ဘယ်အချိန် ထွက်မလဲလို့ သူမ မေးခဲ့တယ်။","question":"Er fragte, ___ sie komme.","options":["ob","denn","aber","oder"]},{"level":"C1","title":"Complex genitive chains","rule":"Formal nouns can include several genitive noun phrases; make the logical relationships clear to avoid ambiguity.","pattern":"die Ergebnisse der Analyse des Projekts","de":"Die Ergebnisse der Untersuchung liegen vor.","en":"The results of the investigation are available.","my":"စစ်ဆေးမှုရလဒ်တွေ ရရှိပြီ။","question":"Die Ergebnisse ___ Untersuchung sind wichtig.","options":["der","die","den","dem"]},{"level":"C1","title":"Apposition structures","rule":"An apposition is a noun phrase identifying or explaining another noun phrase; punctuation depends on whether it is additional or integrated.","pattern":"Hamburg, eine Hafenstadt, ...","de":"Hamburg, eine große Hafenstadt, liegt im Norden.","en":"Hamburg, a major port city, is in the north.","my":"ဟမ်းဘတ်ဟာ မြောက်ဘက်မှာရှိတဲ့ ဆိပ်ကမ်းမြို့ကြီးတစ်မြို့ပါ။","question":"Hamburg, ___ Hafenstadt, ...","options":["eine","einen","einer","eines"]},{"level":"C1","title":"Conditional inversion","rule":"A conditional clause without wenn often begins with the finite verb; in formal style it can express hypothetical conditions.","pattern":"Hätte ich Zeit, ...","de":"Hätte ich Zeit, würde ich helfen.","en":"If I had time, I would help.","my":"အချိန်ရှိခဲ့ရင် ကူညီမယ်။","question":"___ ich Zeit, würde ich kommen.","options":["Hätte","Habe","Hatten","Habt"]},{"level":"C1","title":"Advanced passive variants","rule":"Formal German can replace a passive with constructions using sich lassen, sein + zu or adjective suffixes such as -bar where appropriate.","pattern":"Das lässt sich erklären.","de":"Das Problem lässt sich lösen.","en":"The problem can be solved.","my":"ဒီပြဿနာကို ဖြေရှင်းနိုင်တယ်။","question":"Das lässt sich leicht ___.","options":["lösen","gelöst","löste","löst"]},{"level":"C1","title":"Hedging and qualification","rule":"Formal writing distinguishes demonstrated facts from possibility using forms like möglicherweise, vermutlich and dürfte.","pattern":"möglicherweise · vermutlich · dürfte","de":"Die Zahlen dürften weiter steigen.","en":"The figures are likely to rise further.","my":"ကိန်းဂဏန်းတွေ ဆက်တက်နိုင်ခြေများတယ်။","question":"Das Ergebnis ist ___ korrekt. (probably)","options":["vermutlich","unbedingt","niemals","keinesfalls"]},{"level":"A1","title":"Verb conjugation","rule":"German finite verbs agree with the subject in person and number. Learn the present-tense endings -e, -st, -t, -en, -t, -en; irregular stems must be learned separately.","pattern":"lernen: lerne, lernst, lernt, lernen","de":"Ihr lernt Deutsch.","en":"You (plural) learn German.","my":"သင်တို့ ဂျာမန်စာ သင်နေကြတယ်။","question":"Ihr ___ heute.","options":["lernt","lernen","lerne","lernst"]},{"level":"A1","title":"Accusative","rule":"The accusative often marks a direct object. The masculine singular definite article becomes den, while die and das stay unchanged.","pattern":"Ich sehe den Hund.","de":"Ich kaufe einen Apfel.","en":"I am buying an apple.","my":"ကျွန်တော် ပန်းသီးတစ်လုံး ဝယ်နေတယ်။","question":"Ich kaufe ___ Apfel.","options":["einen","ein","einem","einer"]},{"level":"A1","title":"Modal verbs müssen","rule":"müssen expresses necessity or obligation; the modal is conjugated and the lexical verb stays infinitive at the end.","pattern":"ich muss · du musst · wir müssen","de":"Wir müssen jetzt gehen.","en":"We have to go now.","my":"အခု ကျွန်တော်တို့ သွားရမယ်။","question":"Du ___ lernen.","options":["musst","müssen","muss","müsst"]},{"level":"A1","title":"Modal verbs wollen","rule":"wollen expresses an intention or desire. Use its finite form with a final infinitive.","pattern":"ich will · du willst · er will","de":"Ich will Deutsch lernen.","en":"I want to learn German.","my":"ကျွန်တော် ဂျာမန်စာ သင်ချင်တယ်။","question":"Er ___ heute kochen.","options":["will","wollen","wollt","willst"]},{"level":"A1","title":"Word order statements","rule":"A German main clause has the finite verb in the second position, not necessarily the second word. The first position can hold a subject, object or time phrase.","pattern":"Morgen | fahre | ich ...","de":"Am Montag arbeite ich.","en":"I work on Monday.","my":"တနင်္လာနေ့ ကျွန်တော် အလုပ်လုပ်တယ်။","question":"Morgen ___ ich nach Berlin.","options":["fahre","fahren","ich fahre","gefahren"]},{"level":"A1","title":"Time expressions","rule":"Dates and times often use am with days, um with clock times and im with months or seasons.","pattern":"am Montag · um acht Uhr · im Mai","de":"Der Kurs beginnt um neun Uhr.","en":"The course begins at nine o'clock.","my":"သင်တန်းက ကိုးနာရီမှာ စတယ်။","question":"Der Termin ist ___ Montag.","options":["am","im","um","an"]},{"level":"A1","title":"Numbers and dates","rule":"German composite numbers 21–99 usually put units before tens: einundzwanzig. Dates commonly use ordinal numbers.","pattern":"einundzwanzig · der dritte Mai","de":"Heute ist der dritte Mai.","en":"Today is the third of May.","my":"ဒီနေ့ မေလ သုံးရက်နေ့ပါ။","question":"21 = ___","options":["einundzwanzig","zwanzigeins","einszwanzig","zweizwanzig"]},{"level":"A1","title":"Prepositions of place","rule":"Local prepositions describe position or movement: neben, vor, hinter, in, auf and an. The following case depends on the preposition and meaning.","pattern":"neben dem Tisch","de":"Die Tasche steht neben dem Stuhl.","en":"The bag is next to the chair.","my":"အိတ်က ကုလားထိုင်ဘေးမှာ ရှိတယ်။","question":"Das Bild hängt ___ der Wand.","options":["an","mit","von","seit"]},{"level":"A1","title":"Dative introduction","rule":"Dative commonly marks the recipient or an indirect object and follows certain verbs and prepositions. Masculine and neuter definite articles become dem.","pattern":"ich gebe dem Kind ...","de":"Ich gebe dem Mann ein Buch.","en":"I give the man a book.","my":"ကျွန်တော် အမျိုးသားကို စာအုပ်တစ်အုပ် ပေးတယ်။","question":"Ich gebe ___ Kind Wasser.","options":["dem","das","den","der"]},{"level":"A1","title":"Simple comparisons","rule":"Use so ... wie for equality and comparative adjective + als for inequality.","pattern":"so groß wie · größer als","de":"Er ist so groß wie ich.","en":"He is as tall as I am.","my":"သူက ကျွန်တော်နဲ့ အရပ်တူတယ်။","question":"Sie ist größer ___ ich.","options":["als","wie","wenn","denn"]},{"level":"A1","title":"Compound nouns","rule":"German often combines nouns into one compound. The final component usually determines grammatical gender and the plural.","pattern":"die Schule + das Buch → das Schulbuch","de":"Das Wörterbuch ist hilfreich.","en":"The dictionary is useful.","my":"အဘိဓာန်က အသုံးဝင်တယ်။","question":"Which article fits Wörterbuch?","options":["das","der","die","den"]},{"level":"A1","title":"Object pronouns","rule":"Personal pronouns change in accusative: mich, dich, ihn, sie, es, uns, euch, sie, Sie.","pattern":"ich → mich · er → ihn","de":"Ich sehe ihn jeden Tag.","en":"I see him every day.","my":"နေ့တိုင်း သူ့ကို မြင်တယ်။","question":"Kennst du ___? (me)","options":["mich","mir","ich","mein"]},{"level":"A1","title":"Prepositions of time","rule":"Temporal prepositions include seit (since/for an ongoing period, dative), vor (ago), ab (from) and bis (until).","pattern":"seit Montag · vor zwei Tagen","de":"Ich wohne seit einem Jahr hier.","en":"I have lived here for one year.","my":"ဒီမှာ နေလာတာ တစ်နှစ်ရှိပြီ။","question":"Ich lerne Deutsch ___ Januar.","options":["seit","mit","bei","aus"]},{"level":"A1","title":"Reflexive basics","rule":"A reflexive pronoun refers back to the subject. For many common verbs it is accusative: ich wasche mich, du wäschst dich.","pattern":"ich wasche mich","de":"Ich wasche mich jeden Morgen.","en":"I wash myself every morning.","my":"မနက်တိုင်း ကိုယ်လက်သန့်ရှင်းရေး လုပ်တယ်။","question":"Du wäschst ___.","options":["dich","dir","mich","du"]},{"level":"A1","title":"Perfekt introduction","rule":"Conversational past often uses a present-tense auxiliary haben or sein plus a past participle at the end.","pattern":"ich habe gelernt","de":"Ich habe gestern gelernt.","en":"I studied yesterday.","my":"မနေ့က စာကျက်ခဲ့တယ်။","question":"Wir haben viel ___.","options":["gelernt","lernen","lerne","lernt"]},{"level":"A1","title":"Simple sentence connectors","rule":"Connect ideas with und (and), aber (but), oder (or) and denn (because). They do not cause verb-final order.","pattern":"und · aber · oder · denn","de":"Ich bin müde, aber ich lerne.","en":"I am tired, but I study.","my":"ပင်ပန်းပေမယ့် စာကျက်တယ်။","question":"Ich lerne, ___ ich habe morgen eine Prüfung.","options":["denn","weil","dass","ob"]},{"level":"A2","title":"Past participles irregular","rule":"Strong verbs frequently take -en in Partizip II and may change their stem vowel; there is no single reliable rule for all strong verbs.","pattern":"sehen → gesehen · schreiben → geschrieben","de":"Ich habe den Film gesehen.","en":"I saw the film.","my":"ကျွန်တော် ရုပ်ရှင်ကို ကြည့်ခဲ့တယ်။","question":"sehen → ___","options":["gesehen","geseht","sehent","gesieht"]},{"level":"A2","title":"Präteritum modal verbs","rule":"In past narration, modal verbs usually use simple past forms like musste, konnte and wollte with a lexical infinitive.","pattern":"ich konnte · er musste","de":"Gestern musste ich arbeiten.","en":"Yesterday I had to work.","my":"မနေ့က အလုပ်လုပ်ရတယ်။","question":"Früher ___ ich nicht schwimmen.","options":["konnte","kann","können","könnt"]},{"level":"A2","title":"Dative pronouns","rule":"Dative personal pronouns include mir, dir, ihm, ihr, uns, euch, ihnen and Ihnen.","pattern":"ich → mir · du → dir","de":"Kannst du mir helfen?","en":"Can you help me?","my":"ကျွန်တော့်ကို ကူညီပေးနိုင်မလား။","question":"Ich helfe ___. (you, informal singular)","options":["dir","dich","du","dein"]},{"level":"A2","title":"Movement vs location","rule":"With two-way prepositions, a destination usually takes accusative and a location dative. Distinguish 'where to?' from 'where?'.","pattern":"in die Küche / in der Küche","de":"Ich gehe in die Küche.","en":"I go into the kitchen.","my":"မီးဖိုချောင်ထဲ သွားတယ်။","question":"Ich bin in ___ Küche.","options":["der","die","den","dem"]},{"level":"A2","title":"Dative verbs","rule":"Some verbs govern dative rather than accusative, for example helfen, danken, gefallen, gehören and antworten.","pattern":"helfen + Dativ","de":"Das Buch gehört meinem Bruder.","en":"The book belongs to my brother.","my":"စာအုပ်က ကျွန်တော့်အစ်ကိုပိုင်တာပါ။","question":"Das gefällt ___ Frau.","options":["der","die","den","das"]},{"level":"A2","title":"Accusative vs dative","rule":"Accusative commonly marks a direct object and dative a recipient, but individual verbs and prepositions control case.","pattern":"Ich gebe dem Kind den Ball.","de":"Ich schicke meiner Mutter eine Nachricht.","en":"I send my mother a message.","my":"အမေ့ကို စာတစ်စောင် ပို့တယ်။","question":"Ich gebe ___ Mann das Buch.","options":["dem","den","der","das"]},{"level":"A2","title":"Adjective endings after indefinite articles","rule":"After ein- words, adjective endings supply missing case/gender information: ein guter Mann, eine gute Frau, ein gutes Kind.","pattern":"ein guter Mann","de":"Er hat einen neuen Laptop.","en":"He has a new laptop.","my":"သူ့မှာ လက်ပ်တော့အသစ်တစ်လုံးရှိတယ်။","question":"Das ist ein ___ Auto.","options":["neues","neue","neuen","neuer"]},{"level":"A2","title":"Adjective endings without article","rule":"Without a determiner, an attributive adjective often carries a strong ending indicating case, gender and number.","pattern":"frischer Kaffee · kaltes Wasser","de":"Ich trinke kaltes Wasser.","en":"I drink cold water.","my":"ရေအေး သောက်တယ်။","question":"Ich trinke ___ Kaffee.","options":["heißen","heißer","heißes","heiße"]},{"level":"A2","title":"Superlative adjectives","rule":"Predicative/adverbial superlatives use am + -sten/-esten; before nouns use declined adjective forms.","pattern":"am schnellsten · der schnellste","de":"Sie läuft am schnellsten.","en":"She runs the fastest.","my":"သူမ အမြန်ဆုံး ပြေးတယ်။","question":"Er lernt am ___.","options":["besten","bester","guten","beste"]},{"level":"A2","title":"Subordinate clauses wenn","rule":"wenn introduces repeated or future conditions/time situations. The finite verb stands at the end of the subordinate clause.","pattern":"wenn ich Zeit habe","de":"Wenn ich Zeit habe, komme ich.","en":"If I have time, I'll come.","my":"အချိန်ရှိရင် လာမယ်။","question":"___ es regnet, bleiben wir hier.","options":["Wenn","Denn","Aber","Oder"]},{"level":"A2","title":"Ob clauses","rule":"ob introduces an indirect yes/no question or uncertainty, equivalent to 'whether/if'; the finite verb comes last.","pattern":"ob sie kommt","de":"Ich weiß nicht, ob er Zeit hat.","en":"I don't know whether he has time.","my":"သူ့မှာ အချိန်ရှိမရှိ မသိဘူး။","question":"Weißt du, ___ sie kommt?","options":["ob","dass","denn","aber"]},{"level":"A2","title":"Reflexive pronouns","rule":"Choose accusative reflexive forms mich/dich/sich or dative mir/dir/sich depending on the verb and other objects.","pattern":"ich wasche mir die Hände","de":"Ich putze mir die Zähne.","en":"I brush my teeth.","my":"သွားတိုက်တယ်။","question":"Ich wasche ___ die Hände.","options":["mir","mich","ich","mein"]},{"level":"A2","title":"Relative clauses basics","rule":"Relative clauses give extra information about a noun; the relative pronoun matches that noun's gender/number and takes case from its role.","pattern":"die Frau, die lacht","de":"Das ist der Mann, der hier wohnt.","en":"That's the man who lives here.","my":"ဒါက ဒီမှာနေတဲ့ အမျိုးသားပါ။","question":"Die Frau, ___ dort steht, ist nett.","options":["die","der","den","dem"]},{"level":"A2","title":"Infinitive with zu","rule":"Many verbs and adjectives take a zu-infinitive clause; zu normally stands just before the infinitive, or between a separable prefix and stem.","pattern":"versuchen, zu lernen","de":"Ich versuche, früh aufzustehen.","en":"I try to get up early.","my":"စောစောထဖို့ ကြိုးစားတယ်။","question":"Ich habe vor, mehr ___ lernen.","options":["zu","um","an","mit"]},{"level":"A2","title":"Temporal prepositions","rule":"Use vor (before/ago), nach (after), seit (since/for), während (during) and bis (until); each has its own case requirements.","pattern":"nach dem Essen · seit Montag","de":"Nach dem Essen gehen wir spazieren.","en":"After eating we go for a walk.","my":"စားပြီးရင် လမ်းလျှောက်ထွက်မယ်။","question":"___ dem Unterricht gehe ich heim.","options":["Nach","Seit","Bis","Um"]},{"level":"A2","title":"Genitive introduction","rule":"Genitive expresses belonging or close noun relationships; masculine and neuter singular nouns typically add -(e)s.","pattern":"das Auto des Mannes","de":"Die Farbe des Hauses ist blau.","en":"The colour of the house is blue.","my":"အိမ်အရောင်က အပြာရောင်ပါ။","question":"Das Fahrrad ___ Kindes ist neu.","options":["des","dem","das","den"]},{"level":"A2","title":"Genitive with names","rule":"Proper names often take -s to express possession; names ending in sibilants may take an apostrophe.","pattern":"Annas Buch · Max' Auto","de":"Das ist Peters Tasche.","en":"This is Peter's bag.","my":"ဒါက ပီတာရဲ့ အိတ်ပါ။","question":"Das ist ___ Buch. (Anna)","options":["Annas","Anna","Annas'","Annan"]},{"level":"A2","title":"Prepositional verbs","rule":"Some verbs regularly pair with a specific preposition and case. Learn both together: warten auf + accusative.","pattern":"warten auf + Akkusativ","de":"Ich warte auf den Bus.","en":"I'm waiting for the bus.","my":"ဘတ်စ်ကားကို စောင့်နေတယ်။","question":"Ich warte ___ den Bus.","options":["auf","bei","mit","zu"]},{"level":"A2","title":"Pronominal adverbs","rule":"For inanimate prepositional objects, German often uses da(r)+preposition (darauf, darüber); questions use wo(r)+preposition.","pattern":"warten darauf · worauf","de":"Ich freue mich darauf.","en":"I'm looking forward to it.","my":"အဲဒါကို မျှော်လင့်နေတယ်။","question":"Worauf wartest du? – Ich warte ___.","options":["darauf","darüber","damit","dazu"]},{"level":"A2","title":"Time manner place","rule":"A common neutral order for adverbials is time, manner, then place, but emphasis and context allow alternatives.","pattern":"heute / mit dem Bus / nach Hause","de":"Ich fahre morgen mit dem Zug nach Berlin.","en":"Tomorrow I travel by train to Berlin.","my":"မနက်ဖြန် ရထားနဲ့ ဘာလင်ကို သွားမယ်။","question":"Ich fahre morgen ___ dem Zug.","options":["mit","an","auf","aus"]},{"level":"A2","title":"Verbs with two objects","rule":"With give-type verbs, the recipient usually takes dative and the thing transferred accusative.","pattern":"jemandem etwas geben","de":"Sie schenkt ihrem Vater ein Buch.","en":"She gives her father a book.","my":"သူမ အဖေ့ကို စာအုပ်လက်ဆောင်ပေးတယ်။","question":"Sie schenkt ___ Vater ein Buch.","options":["ihrem","ihren","ihr","ihres"]},{"level":"A2","title":"Imperative revision","rule":"Imperatives vary by addressee: Komm! (du), Kommt! (ihr), Kommen Sie! (formal). The subject is usually omitted with du/ihr.","pattern":"Lies! · Lest! · Lesen Sie!","de":"Bitte lesen Sie den Text!","en":"Please read the text!","my":"ကျေးဇူးပြုပြီး စာသားကို ဖတ်ပါ။","question":"___ Sie bitte hier!","options":["Warten","Wartet","Warte","Wartest"]},{"level":"A2","title":"Prepositions with genitive","rule":"Common formal genitive prepositions include wegen, trotz, während and statt; informal usage may vary by region.","pattern":"während des Kurses","de":"Trotz des Regens gehen wir raus.","en":"Despite the rain we go outside.","my":"မိုးရွာပေမယ့် အပြင်ထွက်မယ်။","question":"___ des Wetters bleiben wir hier.","options":["Wegen","Weil","Aber","Denn"]},{"level":"A2","title":"Passive introduction","rule":"The process passive focuses on an action or affected entity: werden + past participle; the doer may be omitted.","pattern":"Das Haus wird gebaut.","de":"Die E-Mail wird gesendet.","en":"The email is being sent.","my":"အီးမေးလ်ကို ပို့နေတယ်။","question":"Der Brief ___ geschrieben.","options":["wird","hat","ist","haben"]},{"level":"A2","title":"Konjunktiv II polite requests","rule":"Could/would constructions soften requests: Könnten Sie ...? or Ich hätte gern ... are conventional polite forms.","pattern":"Könnten Sie mir helfen?","de":"Ich hätte gern einen Kaffee.","en":"I'd like a coffee.","my":"ကော်ဖီတစ်ခွက် လိုချင်ပါတယ်။","question":"___ Sie mir bitte helfen?","options":["Könnten","Können","Konnte","Könnt"]},{"level":"B1","title":"Relative clauses with prepositions","rule":"A relative pronoun follows a preposition required by the clause. Its case is governed by that preposition, while gender and number refer back to the antecedent.","pattern":"der Mann, mit dem ich spreche","de":"Das ist die Frau, mit der ich arbeite.","en":"That is the woman I work with.","my":"ဒါက ကျွန်တော်နဲ့ အတူ အလုပ်လုပ်တဲ့ အမျိုးသမီးပါ။","question":"Der Mann, mit ___ ich rede, ist nett.","options":["dem","den","der","das"]},{"level":"B1","title":"Passive perfect","rule":"The Perfekt of process passive combines sein + Partizip II + worden (not geworden).","pattern":"ist gebaut worden","de":"Die Straße ist repariert worden.","en":"The road has been repaired.","my":"လမ်းကို ပြင်ဆင်ပြီးပြီ။","question":"Der Bericht ist geschrieben ___.","options":["worden","geworden","werden","wurde"]},{"level":"B1","title":"Passive with modal verbs","rule":"A modal verb combines with a passive infinitive (Partizip II + werden): muss repariert werden.","pattern":"muss gemacht werden","de":"Das Auto muss repariert werden.","en":"The car must be repaired.","my":"ကားကို ပြင်ရမယ်။","question":"Die Tür muss geschlossen ___.","options":["werden","worden","wurde","ist"]},{"level":"B1","title":"Irrealis conditionals","rule":"For unreal present conditions, use Konjunktiv II in both clauses: Wenn ich Zeit hätte, würde ich kommen.","pattern":"wenn ich könnte","de":"Wenn ich Geld hätte, würde ich reisen.","en":"If I had money, I would travel.","my":"ပိုက်ဆံရှိခဲ့ရင် ခရီးသွားမယ်။","question":"Wenn ich frei ___, käme ich.","options":["wäre","bin","ist","sein"]},{"level":"B1","title":"Past unreal conditions","rule":"Use Konjunktiv II past (hätte/wäre + Partizip II) for past events that did not happen.","pattern":"hätte gelernt · wäre gekommen","de":"Wenn ich gelernt hätte, hätte ich bestanden.","en":"If I had studied, I would have passed.","my":"စာကျက်ခဲ့ရင် အောင်ခဲ့မှာပါ။","question":"Wenn er früher gekommen ___, hätte er sie gesehen.","options":["wäre","ist","war","hat"]},{"level":"B1","title":"Infinitive clauses ohne zu","rule":"ohne ... zu describes an action not occurring alongside the main action. The subject is understood from the main clause.","pattern":"ohne zu fragen","de":"Er ging, ohne sich zu verabschieden.","en":"He left without saying goodbye.","my":"နှုတ်မဆက်ဘဲ သူ ထွက်သွားတယ်။","question":"Sie ging, ___ etwas zu sagen.","options":["ohne","um","damit","weil"]},{"level":"B1","title":"Infinitive clauses statt zu","rule":"(an)statt ... zu introduces an alternative action that was not chosen.","pattern":"statt zu lernen","de":"Er spielt, statt zu lernen.","en":"He plays instead of studying.","my":"စာမကျက်ဘဲ ကစားနေတယ်။","question":"Sie schläft, ___ zu arbeiten.","options":["statt","weil","dass","ob"]},{"level":"B1","title":"Temporal clauses während","rule":"während + finite clause expresses two simultaneous situations; it places the finite verb at the end of the subordinate clause.","pattern":"während sie lernt","de":"Während ich lese, hört er Musik.","en":"While I read, he listens to music.","my":"ကျွန်တော် စာဖတ်နေချိန် သူ သီချင်းနားထောင်တယ်။","question":"___ sie kocht, decke ich den Tisch.","options":["Während","Nachdem","Bevor","Seitdem"]},{"level":"B1","title":"Als vs wenn","rule":"Use als for a single past event/period; wenn for recurring events, present/future time or conditions.","pattern":"als ich klein war / wenn ich Zeit habe","de":"Als ich jung war, lebte ich in Yangon.","en":"When I was young, I lived in Yangon.","my":"ငယ်ငယ်တုန်းက ရန်ကုန်မှာ နေခဲ့တယ်။","question":"___ ich zehn war, zog ich um.","options":["Als","Wenn","Ob","Dass"]},{"level":"B1","title":"Since clauses seitdem","rule":"seitdem marks the starting point of a continuing situation; a subordinate clause takes verb-final order.","pattern":"seitdem ich hier wohne","de":"Seitdem ich hier wohne, lerne ich Deutsch.","en":"Since I've lived here, I've been learning German.","my":"ဒီမှာ နေကတည်းက ဂျာမန်စာ သင်လာတယ်။","question":"___ ich studiere, lese ich viel.","options":["Seitdem","Bevor","Obwohl","Damit"]},{"level":"B1","title":"Until clauses bis","rule":"bis expresses an endpoint in time; a finite subordinate clause takes its verb at the end.","pattern":"bis der Zug kommt","de":"Warte, bis ich fertig bin.","en":"Wait until I'm finished.","my":"ကျွန်တော် ပြီးတဲ့အထိ စောင့်ပါ။","question":"Ich bleibe hier, ___ du kommst.","options":["bis","seitdem","obwohl","denn"]},{"level":"B1","title":"Causality da","rule":"da introduces a reason, often presumed or already known, and takes verb-final subordinate order; it is common in formal text.","pattern":"Da es regnet, ...","de":"Da er krank ist, bleibt er zu Hause.","en":"Since he is ill, he stays home.","my":"သူ နေမကောင်းလို့ အိမ်မှာနေတယ်။","question":"___ die Straße gesperrt ist, fahren wir anders.","options":["Da","Aber","Oder","Denn"]},{"level":"B1","title":"Concession obwohl","rule":"obwohl marks unexpected contrast: the main clause remains true despite the subordinate-clause circumstance.","pattern":"obwohl ich müde bin","de":"Obwohl er wenig Zeit hat, hilft er.","en":"Although he has little time, he helps.","my":"အချိန်နည်းပေမယ့် သူ ကူညီတယ်။","question":"___ es kalt ist, gehe ich hinaus.","options":["Obwohl","Weil","Damit","Dass"]},{"level":"B1","title":"Consequence sodass","rule":"sodass introduces a result or consequence with the verb at the end.","pattern":"so ... dass / sodass","de":"Es war laut, sodass ich nichts hörte.","en":"It was loud, so I couldn't hear anything.","my":"အသံဆူလွန်းလို့ ဘာမှ မကြားရဘူး။","question":"Er sprach leise, ___ niemand ihn hörte.","options":["sodass","weil","obwohl","ob"]},{"level":"B1","title":"Double connectors weder noch","rule":"weder ... noch means neither ... nor and connects two rejected possibilities; avoid adding a separate nicht.","pattern":"weder Kaffee noch Tee","de":"Ich trinke weder Kaffee noch Tee.","en":"I drink neither coffee nor tea.","my":"ကော်ဖီလည်းမသောက်၊ လက်ဖက်ရည်လည်း မသောက်ဘူး။","question":"Ich habe ___ Zeit noch Geld.","options":["weder","sowohl","entweder","zwar"]},{"level":"B1","title":"Double connectors sowohl als auch","rule":"sowohl ... als auch includes both linked elements, meaning 'both ... and'.","pattern":"sowohl A als auch B","de":"Sie spricht sowohl Deutsch als auch Englisch.","en":"She speaks both German and English.","my":"သူမ ဂျာမန်နဲ့ အင်္ဂလိပ် နှစ်ဘာသာလုံး ပြောတတ်တယ်။","question":"Er lernt sowohl Deutsch ___ auch Französisch.","options":["als","oder","noch","denn"]},{"level":"B1","title":"Adjective declension review","rule":"The case, gender, number and preceding determiner determine weak, mixed or strong adjective endings; check all four before choosing.","pattern":"der neue Film / ein neuer Film","de":"Ich spreche mit einem netten Mann.","en":"I am talking with a nice man.","my":"ဖော်ရွေတဲ့ အမျိုးသားတစ်ယောက်နဲ့ စကားပြောနေတယ်။","question":"Ich sehe einen ___ Film.","options":["guten","guter","gutes","gute"]},{"level":"B1","title":"Genitive pronouns","rule":"Genitive forms of personal pronouns are rare in modern use, while possessive determiners and relative deren/dessen are frequent.","pattern":"dessen Auto · deren Haus","de":"Der Mann, dessen Auto kaputt ist, wartet.","en":"The man whose car is broken is waiting.","my":"ကားပျက်နေတဲ့ အမျိုးသားက စောင့်နေတယ်။","question":"Die Frau, ___ Tasche fehlt, sucht sie.","options":["deren","dessen","der","dem"]},{"level":"B1","title":"Nominalization basics","rule":"German forms nouns from verbs and adjectives; nominalized infinitives take neuter gender and capitals: das Lesen.","pattern":"lesen → das Lesen","de":"Das Schwimmen macht Spaß.","en":"Swimming is fun.","my":"ရေကူးတာ ပျော်စရာကောင်းတယ်။","question":"___ Lesen hilft beim Lernen.","options":["Das","Der","Die","Den"]},{"level":"B1","title":"Participle adjectives","rule":"Present participle (Partizip I) often has active/current meaning; past participle (Partizip II) often indicates completed or passive meaning.","pattern":"lachend / geschlossen","de":"Das schlafende Kind ist ruhig.","en":"The sleeping child is quiet.","my":"အိပ်နေတဲ့ကလေးက ငြိမ်နေတယ်။","question":"Das ___ Kind ist müde.","options":["spielende","spielen","gespielt","spielend"]},{"level":"B1","title":"Verbs with fixed prepositions","rule":"Certain verbs pair with a fixed preposition and case; learn as a unit: sich interessieren für + accusative.","pattern":"sich freuen auf + Akk.","de":"Ich interessiere mich für Technik.","en":"I'm interested in technology.","my":"နည်းပညာကို စိတ်ဝင်စားတယ်။","question":"Er denkt ___ seine Zukunft.","options":["an","auf","mit","aus"]},{"level":"B1","title":"Prepositional questions","rule":"Ask about a thing using wo(r)+preposition and about people with preposition + interrogative pronoun (mit wem, auf wen).","pattern":"worauf? / auf wen?","de":"Worüber sprichst du?","en":"What are you talking about?","my":"ဘာအကြောင်း ပြောနေကြတာလဲ။","question":"___ wartest du? – Auf den Bus.","options":["Worauf","Womit","Woran","Wofür"]},{"level":"B1","title":"Indirect speech introduction","rule":"Indirect speech reports another person's words without direct quotation. Clauses may use dass or a subjunctive form.","pattern":"Er sagt, er sei müde.","de":"Er behauptet, er habe Recht.","en":"He claims he is right.","my":"သူ မှန်တယ်လို့ အခိုင်အမာ ပြောတယ်။","question":"Sie sagt, sie ___ krank.","options":["sei","seien","sind","haben"]},{"level":"B1","title":"Sequence of tenses","rule":"Express the chronology of events clearly: Plusquamperfekt can establish an event earlier than another past event; not every subordinate clause mechanically shifts tense.","pattern":"Nachdem er gegessen hatte, ging er.","de":"Als ich ankam, war der Film schon angefangen.","en":"When I arrived, the film had already started.","my":"ကျွန်တော် ရောက်တော့ ရုပ်ရှင် စပြီးသား ဖြစ်နေတယ်။","question":"Als ich ankam, ___ sie schon gegangen.","options":["war","ist","wird","hat"]},{"level":"B1","title":"Word order complex clauses","rule":"German subordinate clauses typically put the finite verb at the end; after an initial subordinate clause, the main-clause finite verb follows immediately.","pattern":"Weil es regnet, bleibe ich.","de":"Wenn ich Zeit habe, besuche ich dich.","en":"If I have time, I'll visit you.","my":"အချိန်ရှိရင် မင်းဆီ လာလည်မယ်။","question":"Wenn es regnet, ___ ich daheim.","options":["bleibe","ich bleibe","bleiben","blieb ich"]},{"level":"B1","title":"Connectors dennoch hingegen","rule":"dennoch marks unexpected continuation (nevertheless); hingegen marks contrast (whereas/on the other hand) and behaves as an adverb.","pattern":"Es regnet. Dennoch gehe ich.","de":"Er arbeitet viel; dennoch ist er zufrieden.","en":"He works a lot; nevertheless he is satisfied.","my":"အလုပ်များပေမယ့် သူ ကျေနပ်တယ်။","question":"Es war schwer; ___ gelang es.","options":["dennoch","weil","obwohl","dass"]},{"level":"B2","title":"Advanced subordinate clause order","rule":"Embedded subordinate clauses retain their own verb-final patterns. Check each clause boundary and distinguish matrix-clause and embedded-clause verbs.","pattern":"weil er sagt, dass sie kommt","de":"Ich weiß, dass er glaubt, dass sie recht hat.","en":"I know that he believes she is right.","my":"သူမ မှန်တယ်လို့ သူ ယုံကြည်တာကို ကျွန်တော် သိတယ်။","question":"Er sagt, dass er glaubt, dass sie ___ .","options":["kommt","kommen","komme","kam sie"]},{"level":"B2","title":"Perfect infinitive","rule":"The perfect infinitive combines a past participle with haben/sein and often conveys anteriority after modals or reporting predicates.","pattern":"gesehen haben · gegangen sein","de":"Sie scheint den Zug verpasst zu haben.","en":"She seems to have missed the train.","my":"သူမ ရထားမမီခဲ့ပုံရတယ်။","question":"Er behauptet, nichts gesehen zu ___.","options":["haben","sein","werden","hat"]},{"level":"B2","title":"Double infinitive","rule":"With a modal verb and another infinitive in perfect constructions, an Ersatzinfinitiv often replaces the expected past participle: hat gehen müssen.","pattern":"hat arbeiten müssen","de":"Ich habe gestern arbeiten müssen.","en":"I had to work yesterday.","my":"မနေ့က အလုပ်လုပ်ခဲ့ရတယ်။","question":"Sie hat früh aufstehen ___.","options":["müssen","gemusst","musste","muss"]},{"level":"B2","title":"Passive alternatives lassen","rule":"sich lassen + infinitive often expresses possibility and may replace können + passive: Der Text lässt sich lesen.","pattern":"lässt sich reparieren","de":"Das Gerät lässt sich leicht bedienen.","en":"The device is easy to operate.","my":"စက်ကို အသုံးပြုရတာ လွယ်တယ်။","question":"Das Problem lässt sich ___.","options":["lösen","gelöst","löst","löste"]},{"level":"B2","title":"Passive in past tenses","rule":"A process passive can be expressed in simple past (wurde gebaut), perfect (ist gebaut worden) and past perfect (war gebaut worden).","pattern":"wurde / ist ... worden","de":"Der Vertrag wurde gestern unterschrieben.","en":"The contract was signed yesterday.","my":"စာချုပ်ကို မနေ့က လက်မှတ်ထိုးခဲ့တယ်။","question":"Der Vertrag ist unterschrieben ___.","options":["worden","geworden","werden","wurde"]},{"level":"B2","title":"Verbal style conversion","rule":"Verbal style uses finite verbs and clauses instead of dense nominal groups, often improving readability.","pattern":"wegen des Sturms → weil es stürmt","de":"Weil es regnet, bleiben wir drin.","en":"Because it's raining, we stay inside.","my":"မိုးရွာလို့ အထဲမှာ နေတယ်။","question":"___ es regnet, bleiben wir drin.","options":["Weil","Wegen","Trotz","Während des"]},{"level":"B2","title":"Participles as adjectives","rule":"Participles used before nouns take ordinary adjective endings; distinguish active simultaneity in Partizip I and completed/passive meanings in Partizip II.","pattern":"die singende Frau · das gelesene Buch","de":"Die geöffneten Fenster sind groß.","en":"The open windows are large.","my":"ဖွင့်ထားတဲ့ ပြတင်းပေါက်တွေ ကြီးတယ်။","question":"Die ___ Tür ist schwer.","options":["geschlossene","geschlossen","schließend","schlossen"]},{"level":"B2","title":"Participle I vs II","rule":"Partizip I (verb + -d) often expresses an ongoing active action; Partizip II can express completion or affected state, depending on the verb.","pattern":"lesend vs gelesen","de":"Das schlafende Kind liegt im Bett.","en":"The sleeping child is in bed.","my":"အိပ်နေတဲ့ ကလေးက အိပ်ရာပေါ်မှာ ရှိတယ်။","question":"Der ___ Brief liegt hier.","options":["geschriebene","schreibende","schreiben","schrieb"]},{"level":"B2","title":"Relative adverbs","rule":"Relative adverbs such as wo, wohin and woher can refer to places, especially after certain spatial nouns; register and alternatives matter.","pattern":"ein Ort, wo ...","de":"Das ist der Ort, wo wir uns trafen.","en":"That's the place where we met.","my":"ဒါက ကျွန်တော်တို့ တွေ့ခဲ့တဲ့ နေရာပါ။","question":"Dort, ___ wir wohnen, ist es ruhig.","options":["wo","was","wer","wen"]},{"level":"B2","title":"Advanced genitive constructions","rule":"Genitive can show complex noun relations and appear after nominalized verbs and formal prepositions. Avoid ambiguous chains.","pattern":"die Analyse des Ergebnisses","de":"Die Ursache des Problems ist bekannt.","en":"The cause of the problem is known.","my":"ပြဿနာရဲ့ အကြောင်းရင်းကို သိပြီးပြီ။","question":"Die Folgen ___ Unfalls sind schwer.","options":["des","dem","den","der"]},{"level":"B2","title":"Conditional falls sofern","rule":"falls means if/in case; sofern can mean provided that or insofar as, depending on context. Both introduce subordinate clauses.","pattern":"falls es regnet","de":"Falls du Zeit hast, melde dich.","en":"If you have time, get in touch.","my":"အချိန်ရှိရင် ဆက်သွယ်ပါ။","question":"___ nötig, rufen wir an.","options":["Falls","Denn","Aber","Oder"]},{"level":"B2","title":"Consecutive clauses","rule":"Consecutive clauses describe an outcome, commonly with sodass or so ... dass. The subordinate verb is final.","pattern":"so müde, dass ...","de":"Es war so heiß, dass wir drinnen blieben.","en":"It was so hot that we stayed inside.","my":"အရမ်းပူလို့ အထဲမှာပဲ နေခဲ့တယ်။","question":"Er sprach so leise, ___ ich ihn nicht hörte.","options":["dass","weil","ob","denn"]},{"level":"B2","title":"Adversative während wohingegen","rule":"während and wohingegen may introduce contrasts; während can also be temporal, so use context to interpret it.","pattern":"A steigt, wohingegen B sinkt","de":"Die Preise steigen, wohingegen die Löhne stagnieren.","en":"Prices rise whereas wages stagnate.","my":"ဈေးနှုန်းတက်ပေမယ့် လုပ်ခလစာ မတက်ဘူး။","question":"Die Kosten steigen, ___ die Erlöse sinken.","options":["wohingegen","damit","sodass","weil"]},{"level":"B2","title":"Final clauses","rule":"Final clauses describe purpose: damit + finite clause or um ... zu + infinitive when the understood subject matches.","pattern":"um zu sparen / damit sie lernt","de":"Wir sprechen langsam, damit alle folgen können.","en":"We speak slowly so everyone can follow.","my":"အားလုံး နားလည်အောင် ဖြည်းဖြည်း ပြောတယ်။","question":"Ich spare, ___ ein Fahrrad zu kaufen.","options":["um","weil","dass","ob"]},{"level":"B2","title":"Correlative connectors","rule":"Paired connectors such as einerseits ... andererseits and zwar ... aber organize balanced or contrasting arguments.","pattern":"einerseits ... andererseits","de":"Einerseits ist es teuer, andererseits ist es nützlich.","en":"On one hand it's expensive; on the other it's useful.","my":"တစ်ဖက်မှာ ဈေးကြီးပေမယ့် အခြားတစ်ဖက်မှာ အသုံးဝင်တယ်။","question":"Einerseits praktisch, ___ kostspielig.","options":["andererseits","entweder","weder","sowohl"]},{"level":"B2","title":"Adverbial clauses of manner","rule":"Indem + subordinate clause states how something is done; dadurch, dass may express a means or contributing mechanism.","pattern":"indem er übt","de":"Man lernt, indem man regelmäßig übt.","en":"You learn by practising regularly.","my":"ပုံမှန် လေ့ကျင့်ခြင်းဖြင့် သင်ယူတယ်။","question":"Sie verbessert sich, ___ sie täglich liest.","options":["indem","obwohl","weil nicht","seit"]},{"level":"B2","title":"Infinitive clause expansions","rule":"Infinitive clauses may include their own objects and adverbials; use zu placement correctly, including in separable verbs.","pattern":"ohne den Text zu lesen","de":"Er versucht, pünktlich anzukommen.","en":"He tries to arrive on time.","my":"အချိန်မှန် ရောက်ဖို့ ကြိုးစားတယ်။","question":"Sie plant, morgen früh ___.","options":["abzufahren","zu abfahren","abfahren zu","abgefahren"]},{"level":"B2","title":"Prepositional noun phrases","rule":"Formal text often uses prepositional groups such as aufgrund, im Hinblick auf and in Bezug auf to condense explanations.","pattern":"in Bezug auf das Thema","de":"In Bezug auf die Kosten gibt es Fragen.","en":"There are questions regarding costs.","my":"ကုန်ကျစရိတ်နဲ့ ပတ်သက်ပြီး မေးခွန်းတွေ ရှိတယ်။","question":"___ Bezug auf die Planung gibt es Kritik.","options":["In","An","Zu","Bei dem"]},{"level":"B2","title":"Subjective meaning of sollen","rule":"sollen can report claims without endorsing them: Er soll krank sein means he is said to be ill.","pattern":"er soll reich sein","de":"Sie soll in Berlin wohnen.","en":"She is said to live in Berlin.","my":"သူမ ဘာလင်မှာ နေတယ်လို့ ပြောကြတယ်။","question":"Er ___ sehr erfahren sein. (reportedly)","options":["soll","muss","darf","kann nicht"]},{"level":"B2","title":"Subjective meaning of wollen","rule":"wollen in an epistemic/reporting sense presents someone's own unverified claim: Er will es gesehen haben.","pattern":"er will es gesehen haben","de":"Er will nichts gewusst haben.","en":"He claims not to have known anything.","my":"ဘာမှ မသိခဲ့ဘူးလို့ သူ ဆိုတယ်။","question":"Sie ___ den Unfall gesehen haben. (claims)","options":["will","muss","darf","sollte"]},{"level":"B2","title":"Konjunktiv II past","rule":"Use hätte/wäre + Partizip II for unreal past, regret or hypothetical past consequences.","pattern":"hätte getan · wäre gegangen","de":"Ich wäre gern früher gekommen.","en":"I would have liked to come earlier.","my":"စောစော လာနိုင်ခဲ့ရင် ကောင်းမှာပဲ။","question":"Wir ___ gern länger geblieben.","options":["wären","sind","haben","werden"]},{"level":"B2","title":"Passive with modal verbs perfect","rule":"A perfect construction combining modal and process passive can have complex auxiliary and double-infinitive placement; many speakers prefer past-tense alternatives.","pattern":"hat gemacht werden müssen","de":"Der Antrag hat geprüft werden müssen.","en":"The application had to be checked.","my":"လျှောက်လွှာကို စစ်ဆေးရခဲ့တယ်။","question":"Der Text hat übersetzt werden ___.","options":["müssen","gemusst","musste","muss"]},{"level":"B2","title":"Negation scope","rule":"Position distinguishes what is denied: nicht alle means not all; alle nicht means none of the individuals. Check quantifiers carefully.","pattern":"nicht alle / alle nicht","de":"Nicht alle Studenten waren da.","en":"Not all students were there.","my":"ကျောင်းသားအားလုံး မလာခဲ့ကြဘူး။","question":"___ alle Antworten sind richtig. (not all)","options":["Nicht","Kein","Nie","Ohne"]},{"level":"B2","title":"Advanced adjective government","rule":"Some predicative adjectives govern cases or prepositions: stolz auf + accusative, bewusst + genitive or dative constructions.","pattern":"stolz auf + Akk.","de":"Sie ist stolz auf ihren Sohn.","en":"She is proud of her son.","my":"သူမ သားကို ဂုဏ်ယူတယ်။","question":"Er ist stolz ___ seine Arbeit.","options":["auf","mit","für","aus"]},{"level":"B2","title":"Verbal prefixes meaning","rule":"German verb prefixes can change lexical meaning and separability: umfahren can be separable or inseparable with different meanings.","pattern":"übersetzen / setzen über","de":"Ich übersetze den Artikel.","en":"I translate the article.","my":"ဆောင်းပါးကို ဘာသာပြန်တယ်။","question":"Er ___ den Satz ins Deutsche.","options":["übersetzt","setzt über","über setzen","übersetzen"]},{"level":"B2","title":"Sentence brackets","rule":"German sentence brackets place the finite verb in the left bracket and participles, infinitives or separated prefixes in the right bracket.","pattern":"hat ... gelesen · steht ... auf","de":"Er hat gestern lange gearbeitet.","en":"He worked a long time yesterday.","my":"မနေ့က သူ အချိန်ကြာကြာ အလုပ်လုပ်ခဲ့တယ်။","question":"Er ___ spät aufgestanden.","options":["ist","hat","wird","war"]},{"level":"B2","title":"Discourse markers","rule":"Markers such as allerdings, darüber hinaus and hingegen guide contrast, addition and stance. They affect sentence organization, not case.","pattern":"allerdings · darüber hinaus","de":"Das ist teuer; allerdings hält es lange.","en":"It's expensive; however, it lasts long.","my":"ဈေးကြီးပေမယ့် ကြာရှည်ခံတယ်။","question":"Es ist schwierig; ___ ist es machbar.","options":["allerdings","weil","dass","ob"]},{"level":"B2","title":"Coherence in argumentation","rule":"An argument should make claim, evidence, contrast and conclusion explicit. Use causal, concessive and inferential connectors accurately.","pattern":"zunächst ... zudem ... folglich","de":"Die Nachfrage sinkt; folglich muss das Angebot angepasst werden.","en":"Demand falls; consequently supply must be adjusted.","my":"ဝယ်လိုအား လျော့လို့ ရောင်းလိုအားကို ပြင်ဆင်ရမယ်။","question":"Die Daten fehlen; ___ ist eine Bewertung schwierig.","options":["daher","obwohl","falls","dass"]},{"level":"C1","title":"Deverbal nouns","rule":"Deverbal nouns turn actions or processes into noun phrases, often with suffixes like -ung or nominalized infinitives. Check the changed argument structure and case.","pattern":"prüfen → die Prüfung","de":"Die Auswertung der Daten dauert lange.","en":"The evaluation of the data takes a long time.","my":"ဒေတာ အကဲဖြတ်ဖို့ အချိန်ကြာတယ်။","question":"prüfen → die ___.","options":["Prüfung","Prüfenheit","prüfen","Prüflichkeit"]},{"level":"C1","title":"Advanced participial phrases","rule":"Expanded attributive participles integrate objects, adverbs and modifiers before a noun; they are frequent in formal writing and need adjective inflection.","pattern":"der gestern veröffentlichte Bericht","de":"Die kürzlich veröffentlichten Zahlen sind wichtig.","en":"The recently published figures are important.","my":"မကြာသေးမီက ထုတ်ပြန်ထားတဲ့ ကိန်းဂဏန်းတွေ အရေးကြီးတယ်။","question":"Die gestern ___ Studie ist interessant.","options":["veröffentlichte","veröffentlicht","veröffentlichen","veröffentlichten"]},{"level":"C1","title":"Participial replacement clauses","rule":"An expanded participial attribute can often be paraphrased by a relative clause, which may be clearer in everyday German.","pattern":"die gestern veröffentlichten Daten = die Daten, die gestern veröffentlicht wurden","de":"Der hier wohnende Mann ist Lehrer.","en":"The man living here is a teacher.","my":"ဒီမှာနေတဲ့ အမျိုးသားက ဆရာပါ။","question":"der dort ___ Mann","options":["wohnende","gewohnt","wohnen","wohnend"]},{"level":"C1","title":"Ellipsis in formal prose","rule":"Ellipsis omits recoverable material from coordinated structures. Use it only when grammatical roles and meaning remain clear.","pattern":"Peter liest Bücher, Anna Zeitungen.","de":"Er spricht Deutsch, sie Englisch.","en":"He speaks German; she speaks English.","my":"သူ ဂျာမန်ပြောတယ်၊ သူမ အင်္ဂလိပ်ပြောတယ်။","question":"Er trinkt Tee, sie ___. (parallel ellipsis)","options":["Kaffee","trinkt Kaffee","zu Kaffee","der Kaffee"]},{"level":"C1","title":"Fronting and topicalization","rule":"The prefield can hold a salient topic, object or long phrase, but a declarative main clause still places the finite verb second.","pattern":"Diesen Punkt halte ich ...","de":"Besonders schwierig ist diese Aufgabe.","en":"This task is particularly difficult.","my":"ဒီအလုပ်က အထူးခက်တယ်။","question":"Diesen Ansatz ___ ich sinnvoll.","options":["finde","ich finde","finden","gefunden"]},{"level":"C1","title":"Right dislocation","rule":"Right dislocation repeats or clarifies a referent at the right edge, often after a resumptive pronoun; it is more conversational and stylistically marked.","pattern":"Er ist nett, dein Kollege.","de":"Sie ist sehr hilfreich, diese Übersicht.","en":"It's very helpful, this overview.","my":"ဒီအကျဉ်းချုပ်က အရမ်းအသုံးဝင်တယ်။","question":"Er ist wirklich nett, ___ Kollege.","options":["dein","deinen","deinem","deines"]},{"level":"C1","title":"Sentence field model","rule":"German clauses can be analyzed by Vorfeld, left bracket, Mittelfeld, right bracket and Nachfeld. This helps identify moved constituents and nested clauses.","pattern":"Heute | hat | er viel | gelernt.","de":"Gestern hat sie lange gearbeitet.","en":"Yesterday she worked for a long time.","my":"မနေ့က သူမ အချိန်ကြာကြာ အလုပ်လုပ်ခဲ့တယ်။","question":"Which word is the finite verb in 'Heute hat er gelernt'?","options":["hat","Heute","er","gelernt"]},{"level":"C1","title":"Verb bracket advanced","rule":"In complex predicates, finite auxiliaries, modals, participles and infinitives occupy organized clause positions. Ersatzinfinitiv can affect placement in subordinate clauses.","pattern":"hat ... machen müssen","de":"Er hat das Problem lösen können.","en":"He was able to solve the problem.","my":"သူ ပြဿနာကို ဖြေရှင်းနိုင်ခဲ့တယ်။","question":"Er hat früh gehen ___.","options":["müssen","gemusst","musste","muss"]},{"level":"C1","title":"Modal nuances dürfen mögen","rule":"Epistemic dürfte often indicates probability; mag express a concession or possibility in certain contexts. Context determines the reading.","pattern":"Das dürfte stimmen.","de":"Das mag zutreffen, erklärt aber nicht alles.","en":"That may be true, but it doesn't explain everything.","my":"အဲဒါ မှန်နိုင်ပေမယ့် အားလုံးကို မရှင်းပြနိုင်ဘူး။","question":"Das ___ zwar stimmen, aber ...","options":["mag","muss nicht","darf nicht","will"]},{"level":"C1","title":"Counterfactual nuanced structures","rule":"Use Konjunktiv II to compare hypothetical and real circumstances, including conditional inversions and counterfactual consequences.","pattern":"Wäre er gekommen, ...","de":"Hätte ich es gewusst, hätte ich anders gehandelt.","en":"Had I known, I would have acted differently.","my":"သိခဲ့ရင် အခြားပုံစံနဲ့ ဆောင်ရွက်ခဲ့မယ်။","question":"___ ich das geahnt, wäre ich früher gegangen.","options":["Hätte","Habe","Hatte","Haben"]},{"level":"C1","title":"Concessive inversion","rule":"Certain concessive constructions use inversion or verb-first word order, especially sei es ... oder ... and mag ... auch.","pattern":"Sei es aus Zeitmangel oder ...","de":"Mag es auch schwierig sein, wir versuchen es.","en":"Difficult though it may be, we will try.","my":"ခက်ခဲပေမယ့် ကြိုးစားမယ်။","question":"___ es auch spät sein, wir gehen.","options":["Mag","Wenn","Weil","Damit"]},{"level":"C1","title":"Agentless construction","rule":"Formal writing often foregrounds processes or findings without specifying an agent; use impersonal passive, man or nominal style as appropriate.","pattern":"Es wird angenommen, dass ...","de":"Es wird über das Thema diskutiert.","en":"The topic is being discussed.","my":"ဒီအကြောင်းအရာကို ဆွေးနွေးနေကြတယ်။","question":"Es ___ intensiv diskutiert.","options":["wird","hat","ist","haben"]},{"level":"C1","title":"Complex verbal-nominal reformulation","rule":"Reformulate verbal clauses as nominal phrases while preserving temporal, causal and logical relations. Beware changing who performs an action.","pattern":"weil man analysiert → aufgrund der Analyse","de":"Nach Prüfung der Unterlagen erfolgt die Entscheidung.","en":"The decision follows review of the documents.","my":"စာရွက်စာတမ်း စစ်ဆေးပြီးမှ ဆုံးဖြတ်မယ်။","question":"___ der Prüfung wird entschieden.","options":["Nach","Nachdem der","Weil der","Dass"]},{"level":"C1","title":"Text cohesion reference","rule":"Academic prose uses pronouns, demonstratives, repetition and controlled lexical substitutes to maintain reference across sentences.","pattern":"diese Ergebnisse · jener Ansatz","de":"Die Studie wurde erweitert. Diese Erweiterung war nötig.","en":"The study was expanded. This expansion was necessary.","my":"လေ့လာမှုကို တိုးချဲ့ခဲ့ပြီး အဲဒီတိုးချဲ့မှု လိုအပ်ခဲ့တယ်။","question":"Die Ergebnisse sind neu. ___ Ergebnisse sind wichtig.","options":["Diese","Dieses","Dieser","Diesen"]},{"level":"C1","title":"Substitution and nominal anaphora","rule":"A later noun phrase can summarize an earlier proposition (dieser Befund, diese Entwicklung). Choose a reference that accurately matches the claim.","pattern":"die Preise steigen → diese Entwicklung","de":"Die Kosten stiegen. Diese Entwicklung überraschte alle.","en":"Costs rose. This development surprised everyone.","my":"ကုန်ကျစရိတ် တက်လာတာကို အားလုံး အံ့အားသင့်ခဲ့တယ်။","question":"Die Lage änderte sich. ___ Veränderung war wichtig.","options":["Diese","Dieser","Dieses","Diesen"]},{"level":"C1","title":"Restrictive vs nonrestrictive relatives","rule":"A relative clause can identify a subset or add supplementary information. German uses commas for both; meaning and prosody determine the distinction.","pattern":"Die Studierenden, die ...","de":"Die Bücher, die ich gekauft habe, sind teuer.","en":"The books that I bought are expensive.","my":"ကျွန်တော် ဝယ်ထားတဲ့ စာအုပ်တွေ ဈေးကြီးတယ်။","question":"Die Bücher, ___ ich gekauft habe, sind neu.","options":["die","denen","deren","der"]},{"level":"C1","title":"Embedded relative clauses","rule":"A relative clause can sit within larger subordinate structures. Track clause boundaries and verb positions to avoid ambiguity.","pattern":"weil der Mann, der dort sitzt, ...","de":"Ich weiß, dass der Mann, der dort sitzt, Arzt ist.","en":"I know the man sitting there is a doctor.","my":"ဟိုမှာ ထိုင်နေတဲ့ အမျိုးသားက ဆရာဝန်ဆိုတာ သိတယ်။","question":"Der Mann, ___ dort sitzt, ist Arzt.","options":["der","den","dem","dessen"]},{"level":"C1","title":"Correlative complex constructions","rule":"Paired constructions express proportionality, restriction or balance: je ... desto; einerseits ... andererseits; nicht nur ... sondern auch.","pattern":"je häufiger, desto leichter","de":"Je mehr wir üben, desto besser werden wir.","en":"The more we practise, the better we get.","my":"လေ့ကျင့်လေလေ ပိုကောင်းလေလေ။","question":"Je früher, ___ besser.","options":["desto","als","ob","denn"]},{"level":"C1","title":"Complex infinitive constructions","rule":"Extended zu-infinitive clauses can contain objects, adverbs and embedded elements. Attach them unambiguously to the correct main-clause controller.","pattern":"ohne die Daten sorgfältig zu prüfen","de":"Er versuchte, die Fehler rechtzeitig zu beheben.","en":"He tried to correct the errors in time.","my":"အမှားတွေကို အချိန်မီ ပြင်ဖို့ ကြိုးစားခဲ့တယ်။","question":"Sie hofft, die Arbeit bald ___ beenden.","options":["zu","um","an","mit"]},{"level":"C1","title":"Prepositional idiomaticity","rule":"Advanced German requires conventional combinations of verbs, adjectives and nouns with specific prepositions. Dictionary examples are more reliable than direct translation.","pattern":"ein Interesse an + Dat.","de":"Es besteht ein Interesse an der Forschung.","en":"There is an interest in the research.","my":"ဒီသုတေသနကို စိတ်ဝင်စားမှု ရှိတယ်။","question":"Sie hat Interesse ___ Physik.","options":["an","mit","bei","aus"]},{"level":"C1","title":"Government and valency","rule":"Verbs determine the number and form of complements: e.g. überzeugen + accusative person + von + dative proposition. Analyze semantic roles.","pattern":"jemanden von etwas überzeugen","de":"Sie überzeugt mich von ihrem Plan.","en":"She convinces me of her plan.","my":"သူမ အစီအစဉ်ကို ကျွန်တော် သဘောတူအောင် ရှင်းပြတယ်။","question":"Er überzeugt sie ___ seiner Idee.","options":["von","für","an","bei"]},{"level":"C1","title":"Nominal phrase density","rule":"Dense noun phrases condense information through genitives, prepositions and extended modifiers but risk obscuring relationships. Revise when clarity suffers.","pattern":"die sorgfältige Überprüfung der Ergebnisse","de":"Die genaue Analyse der Daten war wichtig.","en":"The precise analysis of the data was important.","my":"ဒေတာကို တိတိကျကျ ခွဲခြမ်းစိတ်ဖြာဖို့ အရေးကြီးခဲ့တယ်။","question":"Die Analyse ___ Daten dauert lange.","options":["der","die","den","dem"]},{"level":"C1","title":"Stylistic register shifts","rule":"Choose suitable forms for academic reports, emails and everyday talk; nominal constructions and subjunctive reporting are often more formal.","pattern":"Ich denke ... / Meines Erachtens ...","de":"Meines Erachtens ist diese Lösung geeignet.","en":"In my view, this solution is suitable.","my":"ကျွန်တော့်အမြင်အရ ဒီဖြေရှင်းချက်က သင့်တော်တယ်။","question":"___ Erachtens ist der Ansatz sinnvoll.","options":["Meines","Mein","Meinem","Meine"]},{"level":"C1","title":"Argumentative syntax","rule":"Use explicit premise, qualification, counterargument and conclusion. Subordinate clauses, contrastive markers and nominal reference help establish structure.","pattern":"zwar ... aber; folglich","de":"Zwar ist der Ansatz teuer, aber er ist wirksam.","en":"The approach is expensive, but effective.","my":"နည်းလမ်းက ဈေးကြီးပေမယ့် ထိရောက်တယ်။","question":"___ ist die Lösung teuer, aber wirksam.","options":["Zwar","Weil","Damit","Ob"]},{"level":"C1","title":"Precision of tense and aspect","rule":"German tense choices distinguish time and anteriority; adverbials and lexical aspect often express distinctions other languages mark morphologically.","pattern":"hatte begonnen / begann","de":"Als wir ankamen, hatte die Sitzung begonnen.","en":"When we arrived, the meeting had begun.","my":"ကျွန်တော်တို့ ရောက်တဲ့အခါ အစည်းအဝေး စပြီးသားဖြစ်နေတယ်။","question":"Als ich kam, ___ er schon gegangen.","options":["war","hat","ist","wird"]},{"level":"C1","title":"Punctuation in complex clauses","rule":"Separate finite subordinate and relative clauses with commas; infinitive groups follow more nuanced comma rules. Punctuation clarifies clause structure.","pattern":"Ich weiß, dass ...","de":"Das Buch, das ich gelesen habe, ist spannend.","en":"The book I read is exciting.","my":"ကျွန်တော် ဖတ်ခဲ့တဲ့စာအုပ်က စိတ်ဝင်စားဖို့ ကောင်းတယ်။","question":"Which punctuation marks the relative clause?","options":["Commas","Semicolons only","No punctuation","Dashes only"]},{"level":"C1","title":"Editing formal academic German","rule":"Revise academic writing for verb agreement, governed case, reference, clause order, information structure, hedging and evidence-based claims.","pattern":"prüfen: Verb · Kasus · Kohärenz","de":"Die Ergebnisse deuten auf einen Zusammenhang hin.","en":"The results suggest a relationship.","my":"ရလဒ်တွေက ဆက်နွယ်မှုတစ်ခု ရှိနိုင်တယ်လို့ ပြနေတယ်။","question":"Die Ergebnisse deuten ___ einen Zusammenhang hin.","options":["auf","mit","bei","aus"]}];
